/**
 * VENDOR REVALIDATION — the case spec.
 *
 * Source: test-cases/Vendor_Revalidation_QA_Automation_Guide.md (Part 2, the
 * 138 automation cases A–I) read against procol-backend rfx-uat-main @
 * 76b986a012 (15 Oct 2026). Every case keeps the guide's id, steps and
 * priority; `expected` is what the BUILD does (what the runner asserts),
 * `guide` is kept where the guide says something else, and `finding` names
 * the bug when the code contradicts the guide or the TRD. Cases the guide did
 * not have — found while reading the code — are marked `added`.
 *
 * `tier` decides how a case runs (prototype/src/checks/revalidation.ts):
 *   read / audit / listing — run every time, change nothing;
 *   config / run — need a Procol employee token (VR_QA_TOKEN) and restore
 *   the config after; dev / manual / ui / code — reported as not run, with why.
 *
 * Generated from this file (npm run reval:gen in prototype/):
 *   prototype/data/api-cases-extra/revalidation.json   runnable cases
 *   test-cases/api-vendor-revalidation.md               the catalog, for people
 *   test-cases/product-vendor-revalidation.md           the 143 manual cases
 *   prototype/config/revalBugs.json                     the findings
 */

export type Tier = "read" | "audit" | "listing" | "config" | "run" | "dev" | "manual" | "ui" | "code" | "ops" | "removed";
export interface RevCase {
  id: string;
  title: string;
  steps: string[];
  /** what the build does — the assertion */
  expected: string;
  /** the guide's expectation, where it differs */
  guide?: string;
  p: "C" | "H" | "M" | "L";
  type: "Neg" | "Pos" | "Edge";
  /** the guide's Auto column (API, API+UI, Dev, Manual, UI) */
  auto: string;
  tier: Tier;
  needs?: string[];
  /** file:line of the rule, short form (see FILES) */
  rule: string;
  /** why a dev / manual / ui / code case is not run */
  why?: string;
  /** bug id in BUGS */
  finding?: string;
  added?: boolean;
  /** what the case sends, for the catalog */
  call?: string;
}

export const FILES: Record<string, string> = {
  CTL: "app/controllers/api/vendor_revalidation_qa_controller.rb",
  SCH: "app/workers/vendor_revalidation/scheduler_worker.rb",
  QTW: "app/workers/vendor_revalidation/qa_trigger_worker.rb",
  RUN: "app/workers/vendor_revalidation/run_worker.rb",
  VW: "app/workers/vendor_revalidation/vendor_worker.rb",
  SW: "app/workers/vendor_revalidation/sweeper_worker.rb",
  VCS: "app/services/vendor_revalidation/vendor_check_service.rb",
  VR: "app/services/vendor_revalidation/value_reader.rb",
  PG: "app/services/vendor_revalidation/provider_guard.rb",
  VAL: "lib/external_api/validation.rb",
  VVH: "app/models/vendor_validation_history.rb",
  CCH: "app/controllers/concerns/companies_controller_helper.rb",
  CC: "app/controllers/api/companies_controller.rb",
  CO: "app/models/company.rb",
  FH: "app/controllers/concerns/companies_controller_filter_helper.rb",
};

export const MODULES: Record<string, { feature: string; title: string; intro: string }> = {
  A: { feature: "revalidation.access", title: "API access and input validation", intro: "Who may call the QA API and every refusal it gives. Config cases PUT a bad config and check it was refused AND left the saved config alone." },
  B: { feature: "revalidation.schedule", title: "Triggers and schedule", intro: "Force vs scheduler, the cycle arithmetic, catch-up, cancel, the shared run id and re-triggers. Scheduler cases set start dates relative to today so every cycle can be proved on the day the suite runs; they read a column that does not exist, so no provider is called." },
  C: { feature: "revalidation.coverage", title: "Vendor coverage", intro: "Which vendors a run picks: link status in vendor_statuses, source referral/procol, active company, sorted by id." },
  D: { feature: "revalidation.values", title: "Reading document values", intro: "Paths are tried in order; the first that gives a value wins. Several cases point a document at a company column on purpose, so the value is known without preparing data." },
  E: { feature: "revalidation.documents", title: "GST, PAN, MSME and bank checks", intro: "The format pre-check runs before any provider call; pointing a document at the wrong column (a PAN read as GST) proves it without touching a provider." },
  F: { feature: "revalidation.provider", title: "Provider limits, outages and deadline", intro: "Mostly dev-assisted. The switch-off mid-run is the one the QA API can stage." },
  G: { feature: "revalidation.status", title: "Final status, errors and history", intro: "failed > system_error > passed > skipped over each document type's latest rows; one error line per failed or system_error row." },
  H: { feature: "revalidation.listing", title: "Vendor listing, vendor page and Excel", intro: "Read with the client's own session on the revalidation host and compared with the database, vendor by vendor." },
  I: { feature: "revalidation.security", title: "Security, logs and onboarding regression", intro: "Masking, the vendor portal, the production guard and switching the feature off." },
  R: { feature: "revalidation.audit", title: "Audit of the runs already recorded", intro: "SELECT-only checks on the client's latest real run — they need no token and change nothing, so they run every time." },
};

